$ErrorActionPreference = "Stop"
$Root = Split-Path -Parent $MyInvocation.MyCommand.Path
Set-Location $Root
function Write-B64([string]$Path,[string]$Data){$full=Join-Path $Root $Path;$dir=Split-Path -Parent $full;New-Item -ItemType Directory -Force -Path $dir|Out-Null;[IO.File]::WriteAllBytes($full,[Convert]::FromBase64String($Data))}
Write-B64 'src/core/rulesets/playStatusRuntime.ts' ''
Write-B64 'src/features/play-mode/PlayStatusRuntimePanel.tsx' ''
Write-B64 'src/core/rulesets/playStatusRuntime-N-MEGA10.test.ts' ''
$play = Join-Path $Root 'src/features/play-mode/PlayMode.tsx'
$text = Get-Content $play -Raw
if ($text -notmatch 'import \{ PlayStatusRuntimePanel \}') {
  $importLine = 'import { PlayStatusRuntimePanel } from "./PlayStatusRuntimePanel";'
  $marker = 'const conditionOptions:'
  $markerIndex = $text.IndexOf($marker)
  if ($markerIndex -lt 0) { throw 'PlayMode import bolgesi bulunamadi.' }
  $text = $text.Insert($markerIndex, $importLine + "`r`n`r`n")
}
if ($text -notmatch '<PlayStatusRuntimePanel') {
  $restPattern = '(?m)^(\s*)<section className="play-mode-card play-mode-rest-card">'
  $match = [regex]::Match($text, $restPattern)
  if (-not $match.Success) { throw 'PlayMode rest paneli bulunamadi.' }
  $indent = $match.Groups[1].Value
  $panel = $indent + '<PlayStatusRuntimePanel character={activeCharacter} onChange={onUpdateCharacter} />' + "`r`n`r`n" + $match.Value
  $text = $text.Substring(0,$match.Index) + $panel + $text.Substring($match.Index + $match.Length)
}
Set-Content -Path $play -Value $text -Encoding UTF8
$testLog = Join-Path $env:TEMP 'e4-nmega10-test.log'
$buildLog = Join-Path $env:TEMP 'e4-nmega10-build.log'
& npm.cmd exec vitest run -- src/core/rulesets/playStatusRuntime-N-MEGA10.test.ts *> $testLog
if ($LASTEXITCODE -ne 0) { Write-Host 'N-MEGA10 RED - TEST'; Get-Content $testLog -Tail 45; exit 1 }
& npm.cmd run build *> $buildLog
if ($LASTEXITCODE -ne 0) { Write-Host 'N-MEGA10 RED - BUILD'; Get-Content $buildLog -Tail 45; exit 1 }
Write-Host 'N-MEGA10 HOTFIX1 GREEN'
